// TRANSMITTER CODE (Hand Module with MPU6050)
#include <Wire.h>
#include <MPU6050.h>

MPU6050 mpu;

void setup() {
  Serial.begin(9600);
  Wire.begin();
  mpu.initialize();

  // Check MPU6050 connection
  if (!mpu.testConnection()) {
    Serial.println("MPU6050 connection failed!");
    while (1);
  }
  Serial.println("Gesture Transmitter Ready!");
}

void loop() {
  int16_t ax, ay, az;
  int16_t gx, gy, gz;

  mpu.getMotion6(&ax, &ay, &az, &gx, &gy, &gz);

  // Calculate tilt angles
  float pitch = atan2(-ax, sqrt(ay * ay + az * az)) * 180 / PI;
  float roll = atan2(ay, sqrt(ax * ax + az * az)) * 180 / PI;

  // Send commands based on tilt
  if (pitch > 30) {
    Serial.write('F'); // Forward
  } else if (pitch < -30) {
    Serial.write('B'); // Backward
  } else if (roll > 30) {
    Serial.write('L'); // Left
  } else if (roll < -30) {
    Serial.write('R'); // Right
  } else {
    Serial.write('S'); // Stop
  }

  delay(100);
}

