  int availableSlots = 0;

  // Update LCD display
  lcd.clear();
  lcd.setCursor(0, 0);
  lcd.print("Smart Parking");
  lcd.setCursor(0, 1);

  // Check each parking slot
  for (int i = 0; i < 3; i++) {
    long distance = getDistance(trigPins[i], echoPins[i]);
    Serial.print("Slot ");
    Serial.print(i + 1);
    Serial.print(": ");
    Serial.print(distance);
    Serial.println(" cm");

    if (distance > 10) { // Slot empty (no object within 10cm)
      availableSlots++;
      if (i == 0) { // Slot 1 specific indicator
        digitalWrite(greenLED, HIGH);
        digitalWrite(redLED, LOW);
      }
    } else { // Slot occupied
      if (i == 0) { // Slot 1 specific indicator
        digitalWrite(redLED, HIGH);
        digitalWrite(greenLED, LOW);
      }
    }
  }

  // Display available slots on LCD
  lcd.print("Slots: ");
  lcd.print(availableSlots);
  lcd.print("/3");

  // Yellow LED indicates system status
  if (availableSlots == 0) {
    digitalWrite(yellowLED, HIGH); // Parking full
  } else {
    digitalWrite(yellowLED, LOW);
  }

  Serial.print("Available Slots: ");
  Serial.print(availableSlots);
  Serial.println("/3");
  Serial.println("--------------------");

  delay(1000);
}

