unsigned long lastMotionTime = 0;
const unsigned long lightDuration = 30000; // 30 seconds

void setup() {
  pinMode(ldrPin, INPUT);
  pinMode(pirPin, INPUT);
  pinMode(relayPin, OUTPUT);
  digitalWrite(relayPin, LOW); // Start with light OFF

  Serial.begin(9600);
  Serial.println("Smart Street Light Ready!");
}

void loop() {
  // Read sensor values
  int lightLevel = analogRead(ldrPin);
  int motion = digitalRead(pirPin);

  // Print sensor values for debugging
  Serial.print("Light Level: ");
  Serial.print(lightLevel);
  Serial.print(", Motion: ");
  Serial.println(motion);

  // Check if it's dark enough
  if (lightLevel < 500) { // Threshold for darkness

    // Check for motion
    if (motion == HIGH) {
      digitalWrite(relayPin, HIGH); // Turn ON light
      lastMotionTime = millis();    // Reset timer
      Serial.println("Motion detected - Light ON");
    }

    // Keep light ON for specified duration after last motion
    if (digitalRead(relayPin) == HIGH) {
      if (millis() - lastMotionTime > lightDuration) {
        digitalWrite(relayPin, LOW); // Turn OFF light
        Serial.println("No motion - Light OFF");
      }
    }

  } else {
    // It's daytime - ensure light is OFF
    digitalWrite(relayPin, LOW);
    Serial.println("Daytime - Light OFF");
  }

  delay(500); // Check twice per second
}

