bool relayStates[] = {false, false, false, false}; // Track relay states

void setup() {
  Serial.begin(9600);

  // Initialize relay pins
  for (int i = 0; i < 4; i++) {
    pinMode(relayPins[i], OUTPUT);
    digitalWrite(relayPins[i], HIGH); // Relays OFF initially (active LOW for most modules)
  }

  Serial.println("Home Automation System Ready!");
  Serial.println("Commands: relay1, relay2, relay3, relay4, all on, all off");
}

// Function to toggle a specific relay
void toggleRelay(int relayNum) {
  if (relayNum >= 1 && relayNum <= 4) {
    int index = relayNum - 1;
    relayStates[index] = !relayStates[index];

    if (relayStates[index]) {
      digitalWrite(relayPins[index], LOW); // Relay ON
      Serial.print("Relay ");
      Serial.print(relayNum);
      Serial.println(" ON");
    } else {
      digitalWrite(relayPins[index], HIGH); // Relay OFF
      Serial.print("Relay ");
      Serial.print(relayNum);
      Serial.println(" OFF");
    }
  }
}

void loop() {
  if (Serial.available() > 0) {
    String command = Serial.readString();
    command.trim();
    command.toLowerCase();

    Serial.print("Command: ");
    Serial.println(command);

    // Process commands
    if (command == "all on") {
      for (int i = 0; i < 4; i++) {
        digitalWrite(relayPins[i], LOW);
        relayStates[i] = true;
      }
      Serial.println("All devices ON");

    } else if (command == "all off") {
      for (int i = 0; i < 4; i++) {
        digitalWrite(relayPins[i], HIGH);
        relayStates[i] = false;
      }
      Serial.println("All devices OFF");

    } else if (command.startsWith("relay")) {
      // Extract relay number (relay1, relay2, etc.)
      int relayNum = command.charAt(5) - '0'; // Get the number character
      if (relayNum >= 1 && relayNum <= 4) {
        toggleRelay(relayNum);
      }
    }
  }
}

#include <Servo.h>

Servo dispenserServo;
int trig = 2;
int echo = 3;

// Function to get distance in cm
long getDistance() {
  digitalWrite(trig, LOW);
  delayMicroseconds(2);
  digitalWrite(trig, HIGH);
  delayMicroseconds(10);
  digitalWrite(trig, LOW);
  long duration = pulseIn(echo, HIGH);
  return duration * 0.034 / 2;
}

void setup() {
  pinMode(trig, OUTPUT);
  pinMode(echo, INPUT);
  dispenserServo.attach(9);
  dispenserServo.write(0); // Start at rest position

  Serial.begin(9600);
  Serial.println("Automatic Sanitizer Dispenser Ready!");
  Serial.println("Place hand within 10cm to dispense");
}

// Function to dispense sanitizer
void dispenseSanitizer() {
  Serial.println("Dispensing sanitizer...");
  dispenserServo.write(90); // Press pump
  delay(500);               // Hold for 0.5 seconds
  dispenserServo.write(0);  // Release pump
  delay(1000);              // Wait before next dispense
  Serial.println("Ready for next user");
}

void loop() {
  long distance = getDistance();
  Serial.print("Distance: ");
  Serial.print(distance);
  Serial.println(" cm");

  if (distance < 10 && distance > 2) { // Hand within 10cm
    dispenseSanitizer();
    delay(3000); // Prevent multiple triggers
  }

  delay(100); // Small delay between readings
}
